+/// Drive every future to completion while respecting the concurrency limit.
+/// Unlike [`concurrently`], errors remain in the returned items so blocking
+/// work that has already started can finish and clean up before its caller
+/// returns.
+pub(super) async fn concurrently_all<T, F>(futures: Vec<F>, limit: usize) -> Vec<T>
+where
+    F: Future<Output = T>,
+{
+    stream::iter(futures)
+        .buffer_unordered(limit.max(1))
+        .collect()
+        .await
+}
